  .wf-brand{font-family:'Kalam',cursive;font-weight:700;font-size:13px;letter-spacing:.02em}
  .wf-body{position:absolute;left:0;right:0;top:34px;bottom:0;display:flex}
  .wf-note{position:absolute;font-family:'Kalam',cursive;font-size:12.5px;line-height:1.25;color:#c0361a;max-width:210px;z-index:6}
  .k{font-size:8.5px;letter-spacing:.09em;color:#a49e90}
  .pj{border:1.2px solid #e0dacf;background:#fff;border-radius:5px;overflow:hidden;display:flex;flex-direction:column}
  .pj .th{height:62px;background:#f4f1ea;display:grid;place-items:center;border-bottom:1px solid #e6e1d6}
  .pj .tx{padding:6px 9px}.pj .tx b{display:block;font-size:11px;font-weight:600;color:#2b2b2b}.pj .tx span{font-size:9.5px;color:#8a8578}
  .cab{width:172px;border-left:1.5px solid #ddd8cd;background:#f6f3ee;padding:12px;display:flex;flex-direction:column;gap:8px}
  .pr{border:1.3px solid #d8d3c9;background:#fff;border-radius:5px;padding:8px 9px;display:flex;flex-direction:column;gap:5px;font-size:9px;color:#8a8578;line-height:1.5}
  .pr .nm{display:flex;align-items:center;gap:6px;font-size:10.5px;font-weight:700;color:#2b2b2b}.pr .nm span{flex:1}
  .add{text-align:center;padding:6px;border:1.3px dashed #cfc9bd;border-radius:5px;font-size:9.5px;color:#8a8578}
  .add.on{border-style:solid;border-color:#ec3013;color:#ec3013;background:#fff}
  .dot{display:inline-block;width:7px;height:7px;border-radius:50%;border:1.2px solid #6b6659;flex:none}
  .scrim{position:absolute;inset:0;background:rgba(40,36,30,.32);z-index:5;display:grid;place-items:center}
  .dlg{background:#fff;border:1.3px solid #cfc9bd;box-shadow:0 14px 34px rgba(0,0,0,.22);font-family:system-ui,sans-serif;font-size:10.5px;color:#2b2b2b;display:flex;flex-direction:column;position:relative}
  .dlg *{box-sizing:border-box}
  .dlg-h{display:flex;align-items:center;gap:7px;padding:9px 12px;border-bottom:1px solid #e6e1d6}
  .dlg-h b{font-family:'Kalam',cursive;font-size:12px;flex:1}
  .dlg-h .sw{color:#ec3013;font-size:9.5px;white-space:nowrap;text-decoration:underline dotted}
  .dlg-h .x{color:#a49e90;font-size:13px;line-height:1}
  .choice{display:flex;align-items:flex-start;gap:10px;border:1.3px solid #d8d3c9;border-radius:5px;padding:10px 11px;background:#fff}
  .choice.pri{border-color:#ec3013;background:#fff5f2}
  .choice .ic{width:26px;height:26px;border-radius:5px;display:grid;place-items:center;flex:none;background:#f4f1ea}
  .choice.pri .ic{background:#ec3013}
  .choice b{display:block;font-size:11px;margin-bottom:2px}
  .choice span{font-size:9.5px;color:#6b6659;line-height:1.4}
  .pin{margin:8px 10px;border:1.4px solid #f0c8bd;background:#fff5f2;border-radius:5px;padding:7px 9px;display:flex;flex-direction:column;gap:3px}
  .pin-k{font-size:8px;letter-spacing:.09em;color:#c0361a;margin-bottom:2px}
  .kv{display:grid;grid-template-columns:52px 1fr;font-size:9.5px;line-height:1.4}
  .kv .lk{color:#a49e90}.kv .lv{color:#2b2b2b;font-weight:600}.kv .lv.off{color:#c9c3b6;font-weight:400}.kv .lv.as{font-weight:400;color:#6b6659}
  .thr{padding:4px 10px 8px;display:flex;flex-direction:column;gap:6px;flex:1}
  .ubub{align-self:flex-end;background:#ece7de;border-radius:8px 8px 2px 8px;padding:4px 8px;font-size:9.5px;max-width:92%}
  .abub{font-size:9.75px;color:#5d584c;line-height:1.45}.abub em{font-style:normal;color:#8a8578}
  .pc{display:flex;align-items:center;gap:8px;border:1.2px solid #d8d3c9;background:#fff;border-radius:5px;padding:6px 7px}
  .pc .ph{width:44px;height:34px;border:1.2px dashed #cfc9bd;background:#f4f1ea;display:grid;place-items:center;font-size:7.5px;color:#a49e90;flex:none;text-align:center}
  .pc .nm{font-weight:600;font-size:10px;flex:1;line-height:1.3}.pc .nm small{display:block;font-weight:400;color:#8a8578;font-size:9px}
  .go{background:#ec3013;color:#fff;font-family:'Kalam',cursive;font-weight:700;font-size:10px;padding:3px 9px;border-radius:4px;white-space:nowrap}
  .go.q{background:#fff;color:#8a8578;border:1.2px solid #cfc9bd;font-family:system-ui;font-weight:400;font-size:9.5px}
  .opts{display:flex;flex-wrap:wrap;gap:4px;align-items:center}
  .opt{border:1.2px solid #cfc9bd;background:#fff;border-radius:11px;padding:2px 8px;font-size:9.5px;color:#4a463f;white-space:nowrap}
  .opt.def{border-color:#2b2b2b;color:#2b2b2b;font-weight:600}
  .opt.pick{border-color:#ec3013;background:#fff5f2;color:#c0361a;font-weight:600}
  .hint{font-size:8.5px;color:#a49e90}
  .sys{font-size:9px;color:#a49e90;border-top:1px dashed #e6e1d6;padding-top:5px;line-height:1.4}
  .inp{margin:0 10px 10px;border:1.5px solid #ec3013;border-radius:14px;background:#fff;padding:5px 10px;font-size:9.5px;color:#9a9486;display:flex;align-items:center;gap:6px}
  .wiz{display:flex;flex:1;min-height:0}
  .wiz-nav{width:104px;border-right:1px solid #e6e1d6;background:#f6f3ee;padding:8px 0;font-size:9.5px;color:#8a8578}
  .wiz-nav div{padding:5px 11px}.wiz-nav .on{background:#fff;color:#2b2b2b;font-weight:600;border-left:2px solid #ec3013}
  .wiz-nav .k{display:block;padding:6px 11px 2px}
  .wiz-body{flex:1;padding:10px 12px;display:flex;flex-direction:column;gap:7px;font-size:10px}
  .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}
  .mdl{border:1.2px solid #ddd8cd;border-radius:4px;background:#fff;padding:6px;display:flex;flex-direction:column;gap:4px;font-size:9px}
  .mdl.on{border-color:#ec3013;box-shadow:inset 0 0 0 1px #ec3013}
  .mdl .ph{height:30px;background:#f4f1ea;border:1px dashed #cfc9bd;display:grid;place-items:center;font-size:7px;color:#a49e90}
  .mdl .nz{display:flex;gap:3px;font-size:8px;color:#8a8578}.mdl .nz span{border:1px solid #cfc9bd;padding:0 3px}.mdl .nz span.on{background:#2b2b2b;color:#fff;border-color:#2b2b2b}
  .dlg-f{display:flex;align-items:center;gap:6px;padding:8px 12px;border-top:1px solid #e6e1d6;font-size:9.5px}
  .bt{border:1.2px solid #cfc9bd;padding:3px 10px;border-radius:4px;color:#4a463f;white-space:nowrap}
</style>
</helmet>
