        // The printer panel's own three. They exist only inside a printer
        // session, which is why they carry no in-app or MCP exposure: the
        // project conversation has no printer card to draw and no panel to
        // draw it in.
        {"printer_identify",
         "Answer which printer this is",
         "The one tool for identifying the printer the person is adding, from the whole packaged catalogue given in this session's "
         "instructions. Every turn answers through this tool, in one of three shapes. \"propose\", one catalogId: a clear match -- draws "
         "the card and fills the pinned one; nozzle in mm (0 when nothing has been said, the model's own default is assumed), plate and "
         "filament empty for what the model ships with, provenance says whether these facts were read from the printer (settled) or are "
         "your stated guess (assumed). \"propose\", two or three catalogIds: genuinely hard to tell apart -- draws each as its own card "
         "with a question that would separate them; nothing is saved or assumed yet. \"ask\", zero to three catalogIds: not enough to go "
         "on -- a question, optionally with candidates shown while you ask. \"unsupported\", no catalogIds: not a printer this app ships a "
         "profile for (reason not_listed), or not a filament printer at all (reason not_fdm). This never adds the printer -- that is the "
         "person's own tap.",
         object_schema(json{{"action", {{"type", "string"}, {"enum", json::array({"propose", "ask", "unsupported"})}}},
                            {"catalogIds", {{"type", "array"}, {"maxItems", 3}, {"items", id}}},
                            {"question", string_schema()},
                            {"say", string_schema()},
                            {"reason", {{"type", "string"}, {"enum", json::array({"not_listed", "not_fdm"})}}},
                            {"nozzle", number_schema()},
                            {"plate", string_schema()},
                            {"filament", string_schema()},
                            {"provenance", {{"type", "string"}, {"enum", json::array({"assumed", "settled"})}}}},
                       json::array({"action", "catalogIds", "say"})),
         object_schema(json{{"action", string_schema()}, {"shown", integer_schema()}}, json::array({"action", "shown"})),
         ActionClass::Mutation,
         ToolExposure::Printer,
         ToolAvailability::Always,
         ToolHandler::PrinterIdentify,
         // It draws a card and fills the pinned one; nothing is saved until
         // the person taps "Add this printer".
         true},
        {"printer_suggest",
         "Offer what to do next",
         "Offer up to three specific things the person can tap instead of typing, such as \"Use 0.3 mm layers\" -- an action each, never a "
         "bare Yes or No, and never an offer to add the printer, which the card already carries. Mark at most one as suggested; hint is a "
         "few muted words under the row, such as \"or a photo of the front\". opensPhotoPicker opens the photo picker directly instead of "
         "sending the label as a message -- use it only for an action such as \"Photo of the label\" that asks for another picture. "
         "Replaces whatever was offered before.",
         object_schema(json{{"actions", {{"type", "array"}, {"minItems", 1}, {"maxItems", 3},
                                         {"items", object_schema(json{{"label", {{"type", "string"}, {"maxLength", 48}}},
                                                                      {"suggested", boolean_schema()},
                                                                      {"opensPhotoPicker", boolean_schema()}},
                                                                 json::array({"label"}))}}},
                            {"hint", {{"type", "string"}, {"maxLength", 48}}}},
                       json::array({"actions"})),
         object_schema(json{{"offered", integer_schema()}}, json::array({"offered"})),
         ActionClass::Mutation,
         ToolExposure::Printer,
         ToolAvailability::Always,
         ToolHandler::PrinterSuggest,
         // Chips are an offer, not a change.
         true},
        {"printer_change",
         "Change this printer",
         "Change the printer this panel is about: its nozzle in mm, the spools loaded on it, or the access code that keeps it connected. "
         "Only what you pass changes. The nozzle moves the printer onto its model's profile for that size, so every project that uses this "
         "printer prints with it. Calling it shows the person an approval card and waits for their decision; say what the printer now is "
         "only after the result says it was applied. The plate belongs to a project, not to a printer, and cannot be changed here.",
         object_schema(json{{"nozzle", number_schema()},
                            {"accessCode", {{"type", "string"}, {"maxLength", 32}}},
                            {"spools", {{"type", "array"}, {"maxItems", 16},
                                        {"items", object_schema(json{{"name", {{"type", "string"}, {"maxLength", 64}}},
                                                                     {"material", {{"type", "string"}, {"maxLength", 32}}},
                                                                     {"colour", {{"type", "string"}, {"maxLength", 9}}}},
                                                                json::array({"name", "material"}))}}}}),
         object_schema(json{{"printer", string_schema()}, {"nozzle", number_schema()}, {"connected", boolean_schema()}},
                       json::array({"printer", "nozzle", "connected"})),
         ActionClass::Mutation,
         ToolExposure::Printer,
         ToolAvailability::Always,
         ToolHandler::PrinterChange},
    };
    // Every change can join a plan; the decoders never see the field.
    // plan_set records the agent's own words and is not a change to group.
    for (ToolDefinition& definition : definitions)
        if (joins_plans(definition))
            definition.input_schema["properties"]["planId"] = {
                {"type", "string"}, {"maxLength", 64},
                {"description", "Only to group two or more changes; leave it out for a single change. Calls with the same planId "
                                "share one approval card and run in order; each returns queued, and you do not hear how they end."}};
    std::sort(definitions.begin(), definitions.end(),
              [](const ToolDefinition& lhs, const ToolDefinition& rhs) { return lhs.name < rhs.name; });
    return definitions;
}
