ToolExecutionCoordinator::ExtensionResult PrinterConversation::execute_tool(ToolHandler handler, const ToolActivity& activity)
{
    ToolExecutionCoordinator::ExtensionResult result;
    if (handler != ToolHandler::PrinterIdentify && handler != ToolHandler::PrinterSuggest &&
        handler != ToolHandler::PrinterChange)
        return result;

    result.handled = true;
    const json arguments = json::parse(activity.arguments_json, nullptr, false);
    if (!arguments.is_object()) {
        result.error = ToolError{"invalid_arguments", "The printer tool arguments are invalid."};
        return result;
    }

    std::optional<ToolError> error;
    json output;
    switch (handler) {
    case ToolHandler::PrinterIdentify: output = identify(arguments, activity.correlation_id, error); break;
    case ToolHandler::PrinterSuggest: output = suggest(arguments); break;
    default: output = change(arguments, error); break;
    }
    if (error) {
        result.error = std::move(error);
        return result;
    }
    m_host.session_changed();
    result.result_json = output.dump();
    return result;
}

std::optional<Agent::ApprovalPreview> PrinterConversation::preview_approval(ToolHandler handler, const ToolActivity& activity) const
{
    if (handler != ToolHandler::PrinterChange)
        return std::nullopt;
    // Only the nozzle change has a wireframe to build to (WP7); a spool or
    // access code change, alone or combined with a nozzle change, keeps the
    // generic card until one exists.
    const json arguments = json::parse(activity.arguments_json, nullptr, false);
    if (!arguments.is_object() || arguments.contains("spools") || arguments.contains("accessCode"))
        return std::nullopt;
    if (!arguments.contains("nozzle") || !arguments["nozzle"].is_number() || arguments["nozzle"].get<double>() <= 0.)
        return std::nullopt;
    if (m_mode != ConversationMode::Change || m_printer.name.empty())
        return std::nullopt;

    const std::string after = nozzle_text(arguments["nozzle"].get<double>());
    Agent::ApprovalPreview preview;
    preview.title         = "Change nozzle";
    preview.subtitle      = m_nozzle.value + " → " + after + " on " + m_printer_fact.value;
    preview.consequence   = "Every project that uses this printer slices for " + after + ".";
    preview.accept_label  = "Set " + after;
    preview.decline_label = "Keep " + m_nozzle.value;
    return preview;
}

void PrinterConversation::collapse_live_printer_blocks()
{
    for (json& block : m_blocks)
json PrinterConversation::change(const json& arguments, std::optional<ToolError>& error)
{
    if (m_mode != ConversationMode::Change || m_printer.name.empty()) {
        error = ToolError{"no_printer", "This session is not about a printer that exists yet."};
        return {};
    }

    ChangePrinterRequest request;
    request.name = m_printer.name;
    if (arguments.contains("nozzle") && arguments["nozzle"].is_number() && arguments["nozzle"].get<double>() > 0.)
        request.nozzle = arguments["nozzle"].get<double>();
    if (arguments.contains("accessCode") && !arguments["accessCode"].get<std::string>().empty())
        request.access_code = arguments["accessCode"].get<std::string>();
    if (arguments.contains("spools") && arguments["spools"].is_array()) {
        std::vector<PrinterSpool> spools;
        for (const json& spool : arguments["spools"])
            spools.push_back(PrinterSpool{spool.value("name", std::string()), spool.value("material", std::string()),
                                          spool.value("colour", std::string())});
        request.spools = std::move(spools);
    }
    if (!request.nozzle && !request.access_code && !request.spools) {
        error = ToolError{"nothing_to_change", "Name the nozzle, the spools or the access code that changed."};
        return {};
    }

    SavedPrinter      changed;
    const std::string problem = m_backend.change_printer(request, changed);
    if (!problem.empty()) {
        error = ToolError{"change_failed", problem};
        return {};
    }

    const double was = m_printer.nozzle;
    m_printer        = changed;
    read_saved_printer();
    // The card that proposed this collapses on its own; the thread still
    // gets one grey line saying what happened, whether a card showed at all
    // (a chip's tap skips it -- see WP7's pre-approval) or not (F25).
    if (request.nozzle && was != changed.nozzle) {
        m_nozzle.provenance = "changed";
        m_host.post_note("Nozzle set to " + m_nozzle.value);
    }
    if (request.spools)
        m_filament.provenance = "changed";
    m_host.printers_changed({});

    return json{{"printer", changed.name}, {"nozzle", changed.nozzle}, {"connected", changed.connected}};
}

// -- Taps on the panel's own cards -------------------------------------------

bool PrinterConversation::handle_page_message(const std::string& type, const json& payload)
{
    if (type != "printer_action")
        return false;

    const std::string action = payload.value("action", std::string());
    const std::string id     = payload.value("id", std::string());
    if (action == "close")
        m_host.close_panel();
    else if (action == "manual_setup") {
        if (m_mode == ConversationMode::Add) {
            // The wizard takes over from here; whatever it installed is on
            // the printer list the panel returns to.
            m_backend.run_manual_setup();
            m_host.printers_changed({});
            m_host.close_panel();
        } else {
            // OrcaSlicer's own printer settings, as "Printer settings…" did
            // before this panel existed. It closes back into this session,
            // which restates the printer as it now is.
            m_backend.open_printer_settings(m_printer_name);
            read_saved_printer();
            m_host.printers_changed({});
            m_host.session_changed();
        }
    } else if (action == "add")
        add_proposed_printer(payload.value("accessCode", std::string()));
    else if (action == "add_anyway")
        add_proposed_printer(payload.value("accessCode", std::string()), /*force=*/true);
    else if (action == "network_pick")
        use_network_printer(id);
    else if (action == "candidate_pick")
        choose_candidate(id);
    else if (action == "reject")
        reject_proposal();
    else if (action == "browse")
        open_browse();
    else if (action == "browse_vendor")
        browse_into_vendor(id);
    else if (action == "browse_back")
        browse_back();
    else if (action == "browse_pick") {
        m_browsing = false;
        m_browse_vendor_id.clear();
        m_host.session_changed();
        choose_candidate(id);
    }
    return true;
}

void PrinterConversation::add_proposed_printer(const std::string& access_code, bool force)
{
    if (!m_proposal.valid)
        return;

    // A network find can stop answering between "Use this" and this tap
    // (WP11); what it already reported is kept either way, so the person
    // decides rather than the app silently adding or refusing.
    if (!force && !m_proposal.device_id.empty()) {
    std::optional<std::string>   access_code;
    std::optional<std::vector<PrinterSpool>> spools;
};

class IPrinterBackend
{
public:
    virtual ~IPrinterBackend() = default;

    // Reads.
    // The whole packaged catalogue, one entry per model, for the agent's
    // identification prompt and for validating the catalogIds it answers
    // with. Excludes kVendorHiddenFromPrinterFlow (see PrinterCatalog.hpp);
    // everywhere else in the app still sees it, including "Set it up myself".
    virtual std::vector<CatalogPrinter>   catalog_models() const = 0;
    virtual std::vector<DiscoveredPrinter> network_printers() const = 0;
    virtual std::vector<SavedPrinter>     saved_printers() const = 0;

    // Writes. Each returns an empty string on success, or a message written
    // for the person explaining what stopped it.
    virtual std::string add_printer(const AddPrinterRequest& request, SavedPrinter& added) = 0;
    virtual std::string change_printer(const ChangePrinterRequest& request, SavedPrinter& changed) = 0;

    // The manual paths behind "Set it up myself": OrcaSlicer's own printer
    // wizard for a new printer, its printer settings for an existing one.
    virtual void run_manual_setup() = 0;
    virtual void open_printer_settings(const std::string& name) = 0;
};

} // namespace Slic3r::GUI::JusPrin::PrinterSetup

