import json,glob
# resolve via inherits within vendor dir
tot=0;resolved=0;pla=0
for vdir in glob.glob('*/'):
    presets={}
    for f in glob.glob(vdir+'machine/*.json'):
        try:d=json.load(open(f))
        except: continue
        if 'name' in d: presets[d['name']]=d
    def get(name,seen=()):
        d=presets.get(name)
        if not d or name in seen: return None
        if d.get('default_filament_profile'): return d['default_filament_profile']
        p=d.get('inherits')
        return get(p,seen+(name,)) if p else None
    for n,d in presets.items():
        if d.get('type')=='machine' and d.get('instantiation')=='true':
            tot+=1; v=get(n)
            if v:
                resolved+=1; s=v[0] if isinstance(v,list) else v
                pla+= 'PLA' in s.upper()
print('instantiable',tot,'resolved default_filament_profile',resolved,'PLA',pla)
EOF
cd ../..; grep -rn "default_filament_profile" src/libslic3r/PresetBundle.cpp | head -5

